namespace fs=std::filesystem;
static void need(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
static std::vector<std::string> split(const std::string& s){std::vector<std::string> v;std::stringstream f(s);std::string x;while(std::getline(f,x,'\t'))v.push_back(x);return v;}
static std::vector<int> primes(){std::vector<int> v;for(int n=2;n<=5000;++n){bool ok=true;for(int d=2;d<=n/d;++d)if(n%d==0){ok=false;break;}if(ok)v.push_back(n);}need(v.size()==669&&v.back()==4999,"prime catalog");return v;}
struct Row{std::string id,run;int bits;bool pub;mpz_class p,n,disc;};
using Matrix=std::vector<std::vector<int>>;
static bool fits(uint32_t mask,const Matrix& c,size_t j,const std::vector<Row>& rows){for(size_t a=0;a<rows.size();++a)if(mask&(uint32_t(1)<<a))for(size_t b=0;b<rows.size();++b)if(!(mask&(uint32_t(1)<<b))&&rows[a].bits==rows[b].bits&&c[a][j]>=c[b][j])return false;return true;}
static std::vector<uint32_t> assignments(const std::vector<Row>& r){std::map<std::string,std::vector<size_t>> groups;for(size_t i=0;i<r.size();++i)groups[r[i].run].push_back(i);std::vector<uint32_t> all{0};for(const auto& g:groups){int k=0;for(size_t i:g.second)k+=r[i].pub;std::vector<uint32_t> one;std::function<void(size_t,int,uint32_t)> choose=[&](size_t j,int left,uint32_t mask){if(left==0){one.push_back(mask);return;}if(g.second.size()-j<static_cast<size_t>(left))return;choose(j+1,left-1,mask|(uint32_t(1)<<g.second[j]));choose(j+1,left,mask);};choose(0,k,0);std::vector<uint32_t> next;for(auto a:all)for(auto b:one)next.push_back(a|b);all=std::move(next);}std::sort(all.begin(),all.end());return all;}
static void output(const fs::path& p,const std::string& s){std::ofstream f(p);need(bool(f),"output creation");f<<s;need(bool(f),"output write");}
static void selftest(){auto ps=primes();need(*(std::upper_bound(ps.begin(),ps.end(),100)-1)==97,"integer cutoff boundary");std::vector<Row> rows(4);for(auto& r:rows){r.bits=7;r.run="toy";}rows[0].pub=rows[1].pub=true;Matrix m{{0},{1},{2},{3}};need(fits(3,m,0,rows),"planted separation");need(!fits(10,m,0,rows),"misordered control");m[2][0]=1;need(!fits(3,m,0,rows),"tie must fail strict inequality");need(assignments(rows).size()==6,"toy label inventory");for(int p:ps){if(p==2)continue;std::vector<bool> square(static_cast<size_t>(p));for(int i=1;i<p;++i)square[static_cast<size_t>(i*i%p)]=true;int n=0;for(int i=1;i<p;++i)n+=square[static_cast<size_t>(i)];need(n==(p-1)/2,"residue catalog control");}std::cout<<"PASS:669 primes,integer boundaries,tie/planted/misordered controls,six toy assignments and residue catalogs\n";}
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}need(argc==4&&std::string(argv[3])=="ACK_FROZEN_CHECKPOINT","cutoff_sweep COHORT FRESH_OUTPUT ACK_FROZEN_CHECKPOINT");std::ifstream in(argv[1]);need(bool(in),"input");std::vector<Row> rows;std::string line;uint32_t actual=0;while(std::getline(in,line)){if(line.empty()||line[0]=='#')continue;auto c=split(line);need(c.size()==9,"columns");Row r;r.id=c[0];r.bits=std::stoi(c[1]);r.run=c[3];need(c[2]=="published"||c[2]=="skipped","role");r.pub=c[2]=="published";need(r.p.set_str(c[5],0)==0&&r.n.set_str(c[7],0)==0,"integers");mpz_class t=r.p+1-r.n;r.disc=t*t-4*r.p;need(r.disc<0&&r.p>5000,"curve invariants");if(r.pub)actual|=uint32_t(1)<<rows.size();rows.push_back(r);}need(rows.size()==21&&__builtin_popcount(actual)==10,"fixed full21 cohort");auto ps=primes();auto masks=assignments(rows);need(masks.size()==4480,"all4480 labels");const size_t k=ps.size();Matrix s(21,std::vector<int>(k)),z=s,inc=s;std::ostringstream chars;chars<<"label\tell\tcharacter\tstrict\tramified\tinclusive\n";for(size_t j=0;j<k;++j){int ell=ps[j];std::vector<bool> sq(static_cast<size_t>(ell));for(int x=0;x<ell;++x)sq[static_cast<size_t>(x*x%ell)]=true;for(size_t i=0;i<21;++i){if(j){s[i][j]=s[i][j-1];z[i][j]=z[i][j-1];inc[i][j]=inc[i][j-1];}if(ell==2){chars<<rows[i].id<<"\t2\tNA_ell2\t0\t0\t0\n";continue;}ulong r=mpz_fdiv_ui(rows[i].disc.get_mpz_t(),static_cast<ulong>(ell));int ch=r==0?0:sq[r]?1:-1;s[i][j]+=ch==1;z[i][j]+=ch==0;inc[i][j]+=ch>=0;chars<<rows[i].id<<'\t'<<ell<<'\t'<<ch<<'\t'<<s[i][j]<<'\t'<<z[i][j]<<'\t'<<inc[i][j]<<'\n';}}
 auto column=[&](int L){return static_cast<size_t>(std::upper_bound(ps.begin(),ps.end(),L)-ps.begin()-1);};const size_t fixed=column(691);std::vector<size_t> family{column(100)};for(size_t j=0;j<k;++j)if(ps[j]>100)family.push_back(j);need(family.size()==645,"all effective integer cutoffs100to5000");std::ostringstream counts,cut,cal;counts<<"label\tbits\trole\tcutoff\tstrict\tramified\tinclusive\n";cut<<"cutoff\tstrict_separates\tinclusive_separates\tmargin192\tmargin224\tmargin239\tmargin256\n";std::vector<std::pair<int,int>> intervals;int start=-1;
 for(int L=100;L<=5000;++L){size_t j=column(L);bool ok=fits(actual,s,j,rows);if(ok&&start<0)start=L;if(!ok&&start>=0){intervals.emplace_back(start,L-1);start=-1;}cut<<L<<'\t'<<ok<<'\t'<<fits(actual,inc,j,rows);for(int bits:{192,224,239,256}){int hi=-1,lo=10000;for(size_t i=0;i<21;++i)if(rows[i].bits==bits){if(rows[i].pub)hi=std::max(hi,s[i][j]);else lo=std::min(lo,s[i][j]);}need(hi>=0&&lo<10000,"paired field margin");cut<<'\t'<<lo-hi;}cut<<'\n';for(size_t i=0;i<21;++i)counts<<rows[i].id<<'\t'<<rows[i].bits<<'\t'<<(rows[i].pub?"published":"skipped")<<'\t'<<L<<'\t'<<s[i][j]<<'\t'<<z[i][j]<<'\t'<<inc[i][j]<<'\n';}if(start>=0)intervals.emplace_back(start,5000);
 int good=0,good_inc=0,good_fixed=0,old_good=0;cal<<"published_mask\tstrict_any_100_5000\tstrict_fixed691\tinclusive_any_100_5000\tstrict_any_2_2000\n";for(uint32_t mask:masks){bool a=false,b=false,old=false;for(size_t j:family){a=a||fits(mask,s,j,rows);b=b||fits(mask,inc,j,rows);}for(size_t j=0;j<k&&ps[j]<=2000;++j)old=old||fits(mask,s,j,rows);bool one=fits(mask,s,fixed,rows);good+=a;good_inc+=b;good_fixed+=one;old_good+=old;cal<<mask<<'\t'<<a<<'\t'<<one<<'\t'<<b<<'\t'<<old<<'\n';}need(old_good==23&&good_fixed==1,"previous frozen calibration reproduction");
 std::ostringstream summary;summary<<"{\"kind\":\"retrospective-cutoff-sweep-100-5000/v1\",\"rows\":21,\"integer_cutoffs\":4901,\"effective_cutoffs\":645,\"odd_prime_character_cells\":14028,\"label_assignments\":4480,\"strict_search_success_assignments\":"<<good<<",\"inclusive_search_success_assignments\":"<<good_inc<<",\"strict_fixed691_success_assignments\":"<<good_fixed<<",\"previous_search_success_assignments\":"<<old_good<<",\"strict_integer_success_intervals\":[";for(size_t i=0;i<intervals.size();++i){if(i)summary<<',';summary<<'['<<intervals[i].first<<','<<intervals[i].second<<']';}summary<<"],\"historical_use_established\":false,\"independent_verification_pending\":true}\n";fs::path out=argv[2];need(!fs::exists(out),"fresh output");fs::create_directories(out);output(out/"characters.tsv",chars.str());output(out/"profiles.tsv",counts.str());output(out/"cutoffs.tsv",cut.str());output(out/"calibration.tsv",cal.str());output(out/"summary.json",summary.str());std::cout<<"Wrote extended retrospective sweep; independent verification pending\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
